// Generated by Cube Creator. Data classes for CubeCreatorConfig.json.
using System;
using UnityEngine;

namespace CubeCreator
{
    [Serializable]
    public class CubeConfig
    {
        public string name;
        public int version;
        public AnimationSettings animation;
        public GlowSettings glow;
        public GlowSettings groutGlow;
        public ClickerSettings clicker;
        public Vector3 bounds; // half extents of the cube in metres
        public ParticleLayer[] particles;
    }

    [Serializable]
    public class AnimationSettings
    {
        public float spinX, spinY;              // revolutions per 4 seconds
        public float bobAmplitude, bobSpeed;    // metres, cycles per second
        public float pulseScale, pulseSpeed;
        public float glowPulse, glowPulseSpeed;
        public float flicker;
        public float scrollU, scrollV;          // texture scroll per second
        public float wobble;
    }

    [Serializable]
    public class GlowSettings
    {
        public string color;
        public float intensity;
    }

    [Serializable]
    public class ClickerSettings
    {
        public bool enabled;
        public float squash;
        public int burstCount;
        public bool hasBurst;
        public ParticleLayer burst;
    }

    [Serializable]
    public class ParticleLayer
    {
        public string name;
        public string sprite;
        public float rate;
        public float lifetime, lifetimeVar;
        public string emitFrom;   // surface | volume | top | bottom | sphere | ring | point | above
        public float emitScale;
        public string direction;  // up | down | outward | inward | random | orbit | swirlUp
        public float speed, speedVar, spread;
        public float gravity, drag, turbulence;
        public float size, sizeEnd;
        public string colorMode;  // gradient | randomHue
        public string colorStart, colorEnd;
        public float brightness, opacity, fadeIn;
        public string blending;   // additive | normal
        public float twinkle;
        public int seed;
    }

    public static class ColorUtil
    {
        public static Color Parse(string hex, Color fallback)
        {
            return !string.IsNullOrEmpty(hex) && ColorUtility.TryParseHtmlString(hex, out var c) ? c : fallback;
        }
    }
}
